1	import type { Incident, Item } from "./claim-office.js";
2	import { claim, insuranceSum, quote } from "./claim-office.js";
3	
4	// A scenario is the parsed input format: a customer and a list of steps to run
5	// against them. Running a scenario is deliberately separate from the CLI that
6	// wraps it — reading stdin, writing stdout and setting an exit status are I/O
7	// concerns, while sequencing steps is not. Keeping them apart lets the step
8	// logic be exercised without a process.
9	
10	// The scenario names a customer by years alone. Previous contracts are not
11	// given: they are derived from the step's position, since each quote step is
12	// itself a contract.
13	export type ScenarioCustomer = {
14	  yearsWithMHPCO: number;
15	};
16	
17	export type Step = {
18	  op: string;
19	  items?: Item[];
20	  policy?: number;
21	  incident?: Incident;
22	};
23	
24	export type Scenario = {
25	  customer: ScenarioCustomer;
26	  steps: Step[];
27	};
28	
29	export type StepResult = {
30	  premium?: number;
31	  payout?: number;
32	  remainingCap?: number;
33	};
34	
35	// Each quote step signs one contract; a claim step does not. So "previous
36	// contracts" counts the quote steps that ran before this one, which is not the
37	// same as the step's own index once claims are interleaved.
38	const previousContractsAt = (steps: Step[], stepIndex: number): number =>
39	  steps.slice(0, stepIndex).filter((step) => step.op === "quote").length;
40	
41	const runQuoteStep = (
42	  customer: ScenarioCustomer,
43	  step: Step,
44	  steps: Step[],
45	  stepIndex: number,
46	): StepResult => ({
47	  premium: quote(
48	    {
49	      yearsWithMHPCO: customer.yearsWithMHPCO,
50	      previousContracts: previousContractsAt(steps, stepIndex),
51	    },
52	    step.items ?? [],
53	  ),
54	});
55	
56	// A claim step names its policy by the index of the quote step that created it.
57	// The cap is twice that policy's insurance sum.
58	const runClaimStep = (step: Step, steps: Step[]): StepResult => {
59	  const insuredItems = steps[step.policy ?? 0].items ?? [];
60	  return claim(
61	    insuredItems,
62	    step.incident as Incident,
63	    2 * insuranceSum(insuredItems),
64	  );
65	};
66	
67	const runStep = (
68	  customer: ScenarioCustomer,
69	  step: Step,
70	  steps: Step[],
71	  stepIndex: number,
72	): StepResult =>
73	  step.op === "claim"
74	    ? runClaimStep(step, steps)
75	    : runQuoteStep(customer, step, steps, stepIndex);
76	
77	export const runScenario = (scenario: Scenario): StepResult[] =>
78	  scenario.steps.map((step, stepIndex) =>
79	    runStep(scenario.customer, step, scenario.steps, stepIndex),
80	  );
