1	export type Customer = {
2	  yearsWithMHPCO: number;
3	  previousContracts: number;
4	};
5	
6	export type Item = {
7	  type: string;
8	  material?: string;
9	  enchantment?: number;
10	  cursed?: boolean;
11	};
12	
13	const PROCESSING_FEE = 5;
14	
15	// The MHPCO rounds every gold amount in its own favour. That single rule points
16	// in opposite arithmetic directions depending on who is paying: money coming in
17	// rounds up, money going out rounds down. Naming both halves keeps the shared
18	// policy visible instead of leaving two bare Math calls that look unrelated.
19	const roundPremiumInMHPCOsFavour = (amount: number): number =>
20	  Math.ceil(amount);
21	
22	const roundPayoutInMHPCOsFavour = (amount: number): number =>
23	  Math.floor(amount);
24	
25	// The MHPCO price list. The spec gives each item type an insurance value and
26	// a base premium together, so they live in one table: the set of known item
27	// types is a single fact, and the two columns cannot drift apart.
28	type PriceListEntry = {
29	  insuranceValue: number;
30	  basePremium: number;
31	};
32	
33	const PRICE_LIST: Record<string, PriceListEntry> = {
34	  sword: { insuranceValue: 1000, basePremium: 100 },
35	  amulet: { insuranceValue: 600, basePremium: 60 },
36	  staff: { insuranceValue: 800, basePremium: 80 },
37	  potion: { insuranceValue: 400, basePremium: 40 },
38	  rune: { insuranceValue: 250, basePremium: 25 },
39	  moonstone: { insuranceValue: 250, basePremium: 25 },
40	};
41	
42	const CURSED_SURCHARGE_RATE = 0.5;
43	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
44	const HIGH_ENCHANTMENT_THRESHOLD = 5;
45	
46	const isKnownItemType = (item: Item): boolean => item.type in PRICE_LIST;
47	
48	const rejectUnknownItemTypes = (items: Item[]): void => {
49	  const unknown = items.find((item) => !isKnownItemType(item));
50	  if (unknown) {
51	    throw new Error(`Unknown item type: ${unknown.type}`);
52	  }
53	};
54	
55	const basePremiumOf = (item: Item): number =>
56	  PRICE_LIST[item.type].basePremium;
57	
58	const insuranceValueOf = (item: Item): number =>
59	  PRICE_LIST[item.type].insuranceValue;
60	
61	const surchargeRateOf = (item: Item): number =>
62	  (item.cursed ? CURSED_SURCHARGE_RATE : 0) +
63	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD
64	    ? HIGH_ENCHANTMENT_SURCHARGE_RATE
65	    : 0);
66	
67	const surchargeOf = (item: Item): number =>
68	  basePremiumOf(item) * surchargeRateOf(item);
69	
70	const sumBasePremiums = (items: Item[]): number =>
71	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
72	
73	const sumItemSurcharges = (items: Item[]): number =>
74	  items.reduce((sum, item) => sum + surchargeOf(item), 0);
75	
76	// Policy-level modifiers are whole percentages of the policy base premium.
77	// Applying them as `amount * percent / 100` keeps the arithmetic exact:
78	// `100 * 110 / 100` is 110, whereas `100 * 1.1` is 110.00000000000001.
79	const applyPercentage = (amount: number, percent: number): number =>
80	  (amount * percent) / 100;
81	
82	const FIRST_INSURANCE_SURCHARGE_PERCENTAGE = 10;
83	const LOYALTY_DISCOUNT_PERCENTAGE = 20;
84	const LOYALTY_YEARS_THRESHOLD = 2;
85	
86	const loyaltyDiscountPercentageOf = (customer: Customer): number =>
87	  customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
88	    ? LOYALTY_DISCOUNT_PERCENTAGE
89	    : 0;
90	
91	const FOLLOW_UP_DISCOUNT_PERCENTAGE = 15;
92	const FOLLOW_UP_CONTRACTS_THRESHOLD = 1;
93	
94	const followUpDiscountPercentageOf = (customer: Customer): number =>
95	  customer.previousContracts >= FOLLOW_UP_CONTRACTS_THRESHOLD
96	    ? FOLLOW_UP_DISCOUNT_PERCENTAGE
97	    : 0;
98	
99	const policyPercentageDeltaOf = (customer: Customer): number =>
100	  FIRST_INSURANCE_SURCHARGE_PERCENTAGE -
101	  loyaltyDiscountPercentageOf(customer) -
102	  followUpDiscountPercentageOf(customer);
103	
104	const BLOCK_SIZE = 3;
105	const BLOCK_BASE_PREMIUM = 60;
106	
107	const isComponentBlock = (sameTypeGroup: Item[]): boolean =>
108	  sameTypeGroup.length === BLOCK_SIZE;
109	
110	const groupByType = (items: Item[]): Item[][] => {
111	  const groups = new Map<string, Item[]>();
112	  for (const item of items) {
113	    const group = groups.get(item.type) ?? [];
114	    group.push(item);
115	    groups.set(item.type, group);
116	  }
117	  return [...groups.values()];
118	};
119	
120	const basePremiumOfGroup = (sameTypeGroup: Item[]): number =>
121	  isComponentBlock(sameTypeGroup)
122	    ? BLOCK_BASE_PREMIUM
123	    : sumBasePremiums(sameTypeGroup);
124	
125	const policyBasePremiumOf = (items: Item[]): number =>
126	  groupByType(items).reduce((sum, group) => sum + basePremiumOfGroup(group), 0);
127	
128	export const quote = (customer: Customer, items: Item[]): number => {
129	  rejectUnknownItemTypes(items);
130	
131	  const policyBasePremium = policyBasePremiumOf(items);
132	  const policyPercentageAdjustment = applyPercentage(
133	    policyBasePremium,
134	    policyPercentageDeltaOf(customer),
135	  );
136	
137	  return roundPremiumInMHPCOsFavour(
138	    policyBasePremium +
139	      sumItemSurcharges(items) +
140	      policyPercentageAdjustment +
141	      PROCESSING_FEE,
142	  );
143	};
144	
145	export type Damage = {
146	  itemType: string;
147	  amount: number;
148	};
149	
150	export type Incident = {
151	  cause: string;
152	  damages: Damage[];
153	};
154	
155	export type ClaimResult = {
156	  payout: number;
157	  remainingCap: number;
158	};
159	
160	export const insuranceSum = (items: Item[]): number =>
161	  items.reduce((sum, item) => sum + insuranceValueOf(item), 0);
162	
163	const DEDUCTIBLE = 100;
164	
165	const HIGH_ENCHANTMENT_CLAIM_THRESHOLD = 8;
166	const HIGH_ENCHANTMENT_REIMBURSEMENT_RATE = 0.5;
167	
168	const reimbursementRateOf = (item: Item): number =>
169	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_CLAIM_THRESHOLD
170	    ? HIGH_ENCHANTMENT_REIMBURSEMENT_RATE
171	    : 1;
172	
173	// Each damage entry carries its own deductible, so reimbursement is decided
174	// per entry and only then summed into the policy-level total.
175	const reimbursementFor = (damage: Damage, item: Item): number =>
176	  damage.amount * reimbursementRateOf(item) - DEDUCTIBLE;
177	
178	// A damage entry names its item by type, so the insured item it refers to has
179	// to be looked up in the policy. Matching is where "is this damage covered?"
180	// gets decided: either it yields the item, or the claim is rejected. Doing it
181	// once, up front, is what lets everything downstream take a CoveredDamage and
182	// never ask again whether the item exists.
183	type CoveredDamage = {
184	  damage: Damage;
185	  item: Item;
186	};
187	
188	// An insured item backs at most one damage entry, so matching *consumes* it:
189	// each match is taken out of the unclaimed pool and cannot back a second entry.
190	// That is what makes two sword damages on a one-sword policy a rejection rather
191	// than a double payout, so the taking is named rather than left as a bare splice.
192	const takeInsuredItemFor = (damage: Damage, unclaimed: Item[]): Item => {
193	  const index = unclaimed.findIndex((item) => item.type === damage.itemType);
194	  if (index === -1) {
195	    throw new Error(`Item type not covered by the policy: ${damage.itemType}`);
196	  }
197	  const [item] = unclaimed.splice(index, 1);
198	  return item;
199	};
200	
201	const matchDamagesToInsuredItems = (
202	  damages: Damage[],
203	  items: Item[],
204	): CoveredDamage[] => {
205	  const unclaimed = [...items];
206	  return damages.map((damage) => ({
207	    damage,
208	    item: takeInsuredItemFor(damage, unclaimed),
209	  }));
210	};
211	
212	const sumReimbursements = (covered: CoveredDamage[]): number =>
213	  covered.reduce((sum, { damage, item }) => sum + reimbursementFor(damage, item), 0);
214	
215	const rejectNegativeDamageAmounts = (damages: Damage[]): void => {
216	  if (damages.some((damage) => damage.amount < 0)) {
217	    throw new Error("Damage amount must not be negative");
218	  }
219	};
220	
221	// The cap is consumed across successive claims, so a claim reads the cap left
222	// before it and reports the cap left after it. Those are two different numbers
223	// and each gets its own name: `remainingCap` alone would mean both at once.
224	export const claim = (
225	  items: Item[],
226	  incident: Incident,
227	  capBeforeClaim: number,
228	): ClaimResult => {
229	  rejectNegativeDamageAmounts(incident.damages);
230	
231	  const reimbursementBeforeCap = sumReimbursements(
232	    matchDamagesToInsuredItems(incident.damages, items),
233	  );
234	  const payout = roundPayoutInMHPCOsFavour(
235	    Math.min(reimbursementBeforeCap, capBeforeClaim),
236	  );
237	  return { payout, remainingCap: capBeforeClaim - payout };
238	};
