const runQuoteStep = (
  customer: ScenarioCustomer,
  step: QuoteStep,
  steps: Step[],
  stepIndex: number,
): StepResult => ({
  premium: quote(
    {
      yearsWithMHPCO: customer.yearsWithMHPCO,
      previousContracts: previousContractsAt(steps, stepIndex),
    },
    step.items,
  ),
});

// A claim step names its policy by the index of the step that created it, so
// the items it is claiming against have to be fetched back out of the scenario.
const insuredItemsOf = (step: ClaimStep, steps: Step[]): Item[] => {
  const policyStep = steps[step.policy];
  if (policyStep?.op !== "quote") {
    throw new Error(`No policy at step index ${step.policy}`);
  }
  return policyStep.items;
};

const runClaimStep = (step: ClaimStep, steps: Step[]): StepResult => {
  const insuredItems = insuredItemsOf(step, steps);
  return claim(insuredItems, step.incident, payoutCapOf(insuredItems));
};

const runStep = (
  customer: ScenarioCustomer,
  step: Step,
  steps: Step[],
  stepIndex: number,
): StepResult =>
